    // the piece sits one row below where it spawned, not reset
    assert.deepEqual(liveCells(),
      spawned.map(([row, col]) => [row + 1, col]))

    // and the player can keep playing on to the end of the game
    let presses = 0
    while (
      screen.queryByTestId('replay-out') === null &&
      presses < 150
    ) {
      await user.keyboard('{Down}')
